mapper.insert:
insert into review_cycles (
    review_card_id, cycle_no, status, target_success_count, successful_review_count, failed_review_count,
    verification_required_after, started_at, completed_at, created_at, updated_at
) values (
    #{reviewCardId}, #{cycleNo}, #{status}, #{targetSuccessCount}, #{successfulReviewCount}, #{failedReviewCount},
    #{verificationRequiredAfter}, #{startedAt}, #{completedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
select coalesce(max(cycle_no), 0)
from review_cycles
where review_card_id = #{reviewCardId}

mapper.update:
update review_cycles
set status = 'COMPLETED', completed_at = #{completedAt}, updated_at = #{completedAt}
where id = #{id} and status = 'IN_PROGRESS'
